extends Node3D

const GRID_SIZE: Vector2i = Vector2i(4, 3)
const KEYCARD_SIZE: Vector2i = Vector2i(2, 1)
const NO_FIT: Vector2i = Vector2i(-1, -1)
const KEYCARD: StringName = &"cargo_airlock_keycard"
const PLAYER_GROUP: StringName = &"player"

@export var keycard_pickup: Node3D
@export var pickup_area: Area3D
@export var airlock: Node3D
@export var open_airlock_button: Button
@export var inventory_status: Label

var _inventory: SpatialInventory = SpatialInventory.new()


func _ready() -> void:
    open_airlock_button.disabled = true
    var error: Error = _inventory.configure(GRID_SIZE)
    if error != OK:
        inventory_status.text = error_string(error)
        return
    pickup_area.body_entered.connect(_on_pickup_entered)
    open_airlock_button.pressed.connect(_open_airlock)
    inventory_status.text = "Find the cargo keycard."


func _on_pickup_entered(body: Node3D) -> void:
    if not body.is_in_group(PLAYER_GROUP):
        return
    var cell: Vector2i = _inventory.find_first_fit(KEYCARD_SIZE)
    if cell == NO_FIT:
        inventory_status.text = "Free two adjacent cells to pick up the card."
        return
    var error: Error = _inventory.try_place(KEYCARD, KEYCARD_SIZE, cell)
    if error != OK:
        return
    keycard_pickup.queue_free()
    open_airlock_button.disabled = false
    inventory_status.text = "Keycard stored. The cargo airlock can now open."


func _open_airlock() -> void:
    if _inventory.remove(KEYCARD) != OK:
        return
    open_airlock_button.disabled = true
    airlock.queue_free()
    inventory_status.text = "Keycard used. The cargo route is open."

extends Node3D

const SUPPLIES: String = "supplies"
const BRIDGES: String = "bridges"
const STARTING_SCRAP: int = 10
const REPAIR_COST: int = 6

@export var repair_button: Button
@export var barricade: Node3D
@export var supply_status: Label

var _stores: TransactionCoordinator = TransactionCoordinator.new()


func _ready() -> void:
    repair_button.disabled = true
    var error: Error = _stores.register_store(
        SUPPLIES, {"scrap": STARTING_SCRAP}, _prepare_supplies
    )
    if error == OK:
        error = _stores.register_store(BRIDGES, {"repaired": false}, _prepare_bridge)
    if error != OK:
        supply_status.text = error_string(error)
        return
    repair_button.pressed.connect(_repair_bridge)
    repair_button.disabled = false
    supply_status.text = "Repair the bridge for %d scrap." % REPAIR_COST


func _repair_bridge() -> void:
    var transaction: GameTransaction = _stores.begin()
    var error: Error = transaction.add_change(
        SUPPLIES, {"cost": REPAIR_COST}, _stores.get_store_revision(SUPPLIES)
    )
    if error == OK:
        error = transaction.add_change(
            BRIDGES, {"repair": true}, _stores.get_store_revision(BRIDGES)
        )
    if error != OK:
        supply_status.text = error_string(error)
        return
    var result: Dictionary = _stores.commit(transaction)
    if not result.ok:
        supply_status.text = result.message
        return

    var supplies: Dictionary = _stores.read_store(SUPPLIES)
    barricade.queue_free()
    repair_button.disabled = true
    supply_status.text = "Bridge open. Scrap remaining: %d" % int(supplies.scrap)


func _prepare_supplies(current: Dictionary, operations: Array, _context: Dictionary) -> Dictionary:
    for operation: Dictionary in operations:
        var cost: int = operation.get("cost", 0)
        if cost <= 0 or cost > int(current.scrap):
            return {"ok": false, "message": "You need more scrap to repair the bridge."}
        current.scrap -= cost
    return {"ok": true, "state": current}


func _prepare_bridge(current: Dictionary, operations: Array, _context: Dictionary) -> Dictionary:
    for operation: Dictionary in operations:
        if current.repaired or not operation.get("repair", false):
            return {"ok": false, "message": "The bridge is already repaired."}
        current.repaired = true
    return {"ok": true, "state": current}

extends Node

const SAFE_ROOM: StringName = &"safe_room"
const MINES: StringName = &"mines"
const PROFILE: String = "campaign"
const SLOT: String = "checkpoint"
const SAVE_APP: String = "demo.mine_campaign"

@export_file("*.tscn") var safe_room_scene: String
@export_file("*.tscn") var mines_scene: String
@export var rest_button: Button
@export var enter_mines_button: Button
@export var retry_button: Button
@export var status: Label

var _game: GameRuntime
var _checkpoint: SaveSlot


func _ready() -> void:
    _set_busy(true)
    var definition: GameDefinition = GameRuntime.configure().with_worlds({
        SAFE_ROOM: {"scene_id": SAFE_ROOM, "path": safe_room_scene},
        MINES: {"scene_id": MINES, "path": mines_scene},
    }).starting_in(SAFE_ROOM).with_saves(SAVE_APP)
    _game = definition.boot(self)
    if _game == null:
        status.text = "Could not start the campaign."
        return
    var result: Dictionary = await _game.start_offline().wait()
    if not result.ok:
        status.text = result.message
        return
    _checkpoint = _game.save_slot(PROFILE, SLOT)
    rest_button.pressed.connect(_rest)
    enter_mines_button.pressed.connect(_enter_mines)
    retry_button.pressed.connect(_retry)
    _set_busy(false)
    status.text = "Safe room. Rest before entering the mines."


func _rest() -> void:
    _set_busy(true)
    var request: SaveRequest = _checkpoint.save().named("Mine entrance")
    request = request.with_context({"region": "Safe room"}).as_autosave()
    var result: Dictionary = await request.submit().wait()
    status.text = "Checkpoint saved." if result.ok else result.message
    _set_busy(false)


func _enter_mines() -> void:
    _set_busy(true)
    var result: Dictionary = await _game.travel_to(MINES).wait()
    status.text = "Mines. Retry to return to your last rest." if result.ok else result.message
    _set_busy(false)


func _retry() -> void:
    _set_busy(true)
    var result: Dictionary = await _checkpoint.restore_latest().wait()
    status.text = "Returned to the saved room." if result.ok else result.message
    _set_busy(false)


func _set_busy(busy: bool) -> void:
    rest_button.disabled = busy
    enter_mines_button.disabled = busy
    retry_button.disabled = busy
    if not busy:
        rest_button.disabled = _game.get_world_id() != SAFE_ROOM

extends Node3D

const VILLAGE: StringName = &"village"
const CAVES: StringName = &"caves"
const PLAYER_GROUP: StringName = &"player"

@export var world_container: Node3D
@export_file("*.tscn") var village_scene: String
@export_file("*.tscn") var caves_scene: String
@export var village_gate: Area3D
@export var zone_label: Label

var _loader: SceneLoadManager


func _ready() -> void:
    _loader = SceneLoadManager.new()
    add_child(_loader)

    var error: Error = _loader.set_world_container(world_container)
    if error == OK:
        error = _loader.register_scene(VILLAGE, village_scene)
    if error == OK:
        error = _loader.register_scene(CAVES, caves_scene)
    if error != OK:
        zone_label.text = error_string(error)
        return

    _loader.load_completed.connect(_on_load_completed)
    _loader.load_failed.connect(_on_load_failed)
    village_gate.body_entered.connect(_on_gate_entered)
    _load(VILLAGE)


func _on_gate_entered(body: Node3D) -> void:
    if not body.is_in_group(PLAYER_GROUP) or _loader.is_loading():
        return
    if _loader.get_current_scene_id() == VILLAGE:
        _load(CAVES)


func _load(scene_id: StringName) -> void:
    var error: Error = _loader.request_load(scene_id)
    zone_label.text = "Loading…" if error == OK else error_string(error)


func _on_load_completed(scene_id: StringName) -> void:
    zone_label.text = "Caves" if scene_id == CAVES else "Village"


func _on_load_failed(_scene_id: StringName, _error: int, message: String) -> void:
    zone_label.text = message

extends Node

const MATCH_ID: String = "hangar_training"
const HANGAR_EPOCH: int = 1
const PLAYERS: String = "players"
const CHARACTERS: String = "characters"
const LOCAL_PLAYER: String = "trainee"
const PILOT: String = "pilot"
const DRONE: String = "repair_drone"
const TOGGLE_LIGHT: String = "toggle_work_light"

@export var pilot_button: Button
@export var drone_button: Button
@export var light_button: Button
@export var drone_light: SpotLight3D
@export var status: Label

var _stores: TransactionCoordinator = TransactionCoordinator.new()
var _possession: PlayerPossession = PlayerPossession.new()
var _router: CommandRouter = CommandRouter.new()
var _sequence: int = 0


func _ready() -> void:
    drone_light.visible = false
    var error: Error = _configure_training()
    if error != OK:
        status.text = error_string(error)
        return
    if not _switch_to(PILOT):
        return
    pilot_button.pressed.connect(_switch_to.bind(PILOT))
    drone_button.pressed.connect(_switch_to.bind(DRONE))
    light_button.pressed.connect(_request_light_toggle)


func _configure_training() -> Error:
    var error: Error = _stores.register_store(PLAYERS, {LOCAL_PLAYER: {}}, _keep_roster)
    if error != OK:
        return error
    error = _stores.register_store(CHARACTERS, {PILOT: {}, DRONE: {}}, _keep_roster)
    if error != OK:
        return error
    error = _possession.configure(_stores, PLAYERS, CHARACTERS)
    if error != OK:
        return error
    error = _router.configure(MATCH_ID, HANGAR_EPOCH, _possession)
    if error != OK:
        return error
    error = _router.register_handler(TOGGLE_LIGHT, _toggle_light, true)
    if error != OK:
        return error
    return _router.set_accepting_commands(true)


func _keep_roster(current: Dictionary, _operations: Array, _context: Dictionary) -> Dictionary:
    return {"ok": true, "state": current}


func _switch_to(character: String) -> bool:
    var revision: int = _possession.get_revision(LOCAL_PLAYER)
    var result: Dictionary = _possession.try_set_primary(LOCAL_PLAYER, character, revision)
    if result.ok:
        status.text = "Controlling the repair drone." if character == DRONE else "Controlling the pilot."
    else:
        status.text = result.message
    return result.ok


func _request_light_toggle() -> void:
    _sequence += 1
    var result: Dictionary = _router.submit(LOCAL_PLAYER, {
        "match_id": MATCH_ID,
        "world_epoch": HANGAR_EPOCH,
        "sequence": _sequence,
        "type": TOGGLE_LIGHT,
        "payload": {},
        "character_id": _possession.get_primary(LOCAL_PLAYER),
        "possession_revision": _possession.get_revision(LOCAL_PLAYER),
    })
    status.text = result.message


func _toggle_light(_player_id: String, intent: Dictionary) -> Dictionary:
    if intent.character_id != DRONE:
        return {"ok": false, "message": "Take control of the drone to use its work light."}
    drone_light.visible = not drone_light.visible
    return {"ok": true, "message": "Drone light on." if drone_light.visible else "Drone light off."}
